export class ProjectsResource {
  constructor(private readonly core: Core) {}

  /** List projects `GET /projects` */
  list(params: ProjectsListParams = {}, options?: RequestOptions): Page<Project, ProjectList> {
    return this.core.list(`/projects`, params, options);
  }

  /** Create a project from a website, or continue a setup `POST /projects` */
  create(body: ProjectsCreateBody, options?: RequestOptions): Promise<Project | ProjectSetup> {
    return this.core.request("POST", `/projects`, { body, options });
  }

  /** Like `create`, but waits while the work runs, then returns the Project. */
  createAndWait(body: ProjectsCreateBody, options?: RequestOptions): Promise<Project> {
    return this.core.wait("POST", `/projects`, { body, options });
  }

  /** One project `GET /projects/{id}` */
  get(id: string, options?: RequestOptions): Promise<Project> {
    return this.core.request("GET", `/projects/${encodeURIComponent(id)}`, { options });
  }

  /** Rename a project, or change its run config `PATCH /projects/{id}` */
  update(id: string, body: ProjectsUpdateBody, options?: RequestOptions): Promise<Project> {
    return this.core.request("PATCH", `/projects/${encodeURIComponent(id)}`, { body, options });
  }

  /** Delete a project with its scans, answers, and recommendations. This cannot be undone `DELETE /projects/{id}` */
  delete(id: string, params: ProjectsDeleteParams, options?: RequestOptions): Promise<void> {
    return this.core.request("DELETE", `/projects/${encodeURIComponent(id)}`, { query: params, options });
  }

}

